// ⚙️ BEÁLLÍTÁSOK — csak ezt a node-ot kell szerkeszteni.
// Új forrás felvétele = új elem a megfelelő listában. Üres lista = az a forrás kimarad.
return [{
  json: {
    // YouTube-csatornák: @handle vagy UC... kezdetű csatornaazonosító
    youtubeChannels: [
      '@tizeslista_hu',
      'UCjFCzjkgSShdRZIVJx3SSlQ',
    ],

    // X-fiókok felhasználóneve (@ nélkül)
    xAccounts: [
      'ChifoiCristian',
    ],

    // Hírlevelek: a feladó e-mail-címe (a Gmail-fiókodból olvassuk)
    emailSenders: [
      'newsletter@example.com',
    ],

    lookbackHours: 24,       // ennél régebbi tartalom nem kerül be (első futásnál is)
    maxItemsPerSource: 5,    // forrásonként legfeljebb ennyi új elem futásonként
    maxCharsPerItem: 12000,  // elemenként ennyi szöveg megy tovább az LLM-nek
    maxImages: 8,            // ennyi X-képet (grafikont) kap meg összesen a modell

    model: 'claude-sonnet-5-5',
    reportLanguage: 'magyar',
    telegramChatId: '-100XXXXXXXXXX',  // csatorna vagy chat azonosítója
  },
}];

// Egy kimeneti elem csatornánként. A @handle-t és a UC... azonosítót is elfogadjuk.
const cfg = $('⚙️ Beállítások').first().json;
return (cfg.youtubeChannels || [])
  .map(c => String(c).trim())
  .filter(Boolean)
  .map(c => ({
    json: {
      channel: c,
      lookup: c.startsWith('UC')
        ? `id=${c}`
        : `forHandle=${encodeURIComponent(c.startsWith('@') ? c : '@' + c)}`,
    },
  }));

// A playlistItems-válaszokból egységes tartalomelemek, a lookback ablakon belül.
const cfg = $('⚙️ Beállítások').first().json;
const since = Date.now() - cfg.lookbackHours * 3600 * 1000;
const out = [];
for (const res of $input.all()) {
  for (const it of res.json.items || []) {
    const s = it.snippet || {};
    const videoId = s.resourceId?.videoId;
    if (!videoId || Date.parse(s.publishedAt) < since) continue;
    out.push({
      json: {
        uid: `youtube:${videoId}`,
        source: 'youtube',
        author: s.channelTitle || '',
        title: s.title || '',
        url: `https://www.youtube.com/watch?v=${videoId}`,
        published: new Date(s.publishedAt).toISOString(),
        text: s.description || '',
        videoId,
      },
    });
  }
}
return out;

// A felirat-kérés kimenete sorrendben megfelel a bemenő videóknak.
// Ha nincs felirat (vagy nincs Supadata-kulcs), a videó leírása marad a szöveg.
const videos = $('YouTube: csak az új videók').all();
return $input.all().map((res, i) => {
  const video = videos[i].json;
  const transcript = typeof res.json.content === 'string' ? res.json.content.trim() : '';
  return {
    json: {
      ...video,
      text: transcript || video.text,
      hasTranscript: Boolean(transcript),
    },
  };
});

const cfg = $('⚙️ Beállítások').first().json;
return (cfg.xAccounts || [])
  .map(u => String(u).trim().replace(/^@/, ''))
  .filter(Boolean)
  .map(userName => ({ json: { userName } }));

// twitterapi.io válasz → egységes elemek. A tweetek helye verziónként eltér:
// néha "tweets", néha "data.tweets". A képeket (grafikonokat) URL-ként visszük tovább.
const cfg = $('⚙️ Beállítások').first().json;
const since = Date.now() - cfg.lookbackHours * 3600 * 1000;
const accounts = $('X: fiókok').all();
const out = [];
$input.all().forEach((res, i) => {
  const payload = res.json || {};
  const tweets = payload.tweets || payload.data?.tweets || [];
  const user = accounts[i]?.json.userName || '';
  for (const tw of tweets.slice(0, cfg.maxItemsPerSource)) {
    const created = Date.parse(tw.createdAt);
    if (!(created >= since)) continue;
    const media = tw.extendedEntities?.media || tw.entities?.media || [];
    out.push({
      json: {
        uid: `x:${tw.id}`,
        source: 'x',
        author: tw.author?.name ? `${tw.author.name} (@${user})` : `@${user}`,
        title: (tw.text || '').slice(0, 90).replace(/\n/g, ' '),
        url: tw.url || `https://x.com/${user}/status/${tw.id}`,
        published: new Date(created).toISOString(),
        text: tw.text || '',
        images: media.filter(m => m.type === 'photo').map(m => m.media_url_https),
      },
    });
  }
});
return out;

// Gmail-keresés a feladókra. Üres lista esetén a hírlevél-ág kimarad.
const cfg = $('⚙️ Beállítások').first().json;
const senders = (cfg.emailSenders || []).map(s => String(s).trim()).filter(Boolean);
if (!senders.length) return [];
const days = Math.max(1, Math.ceil(cfg.lookbackHours / 24));
return [{ json: { q: `from:(${senders.join(' OR ')}) newer_than:${days}d` } }];

const cfg = $('⚙️ Beállítások').first().json;
const since = Date.now() - cfg.lookbackHours * 3600 * 1000;
return $input.all()
  .map(r => r.json)
  .filter(m => m.id && !m.error)
  .filter(m => !m.date || Date.parse(m.date) >= since)
  .map(m => {
    const from = m.from?.value?.[0] || {};
    return {
      json: {
        uid: `email:${m.id}`,
        source: 'email',
        author: from.name || from.address || m.from?.text || '',
        title: m.subject || '(tárgy nélkül)',
        url: `https://mail.google.com/mail/u/0/#all/${m.id}`,
        published: new Date(m.date || Date.now()).toISOString(),
        text: (m.text || '').trim(),
      },
    };
  });

// Az összes új elemből egyetlen Claude-kérés: szöveg + az X-posztok képei.
const cfg = $('⚙️ Beállítások').first().json;
const items = $input.all().map(i => i.json).filter(j => j.uid);
if (!items.length) return [];

const LABEL = { youtube: 'YouTube-videó', x: 'X-poszt', email: 'Hírlevél' };
const order = { youtube: 0, x: 1, email: 2 };
items.sort((a, b) =>
  order[a.source] - order[b.source] ||
  a.author.localeCompare(b.author) ||
  a.published.localeCompare(b.published));

const system = `Tartalomfigyelő asszisztens vagy. A felhasználó által követett YouTube-csatornák,
X-fiókok és hírlevelek új tartalmából ${cfg.reportLanguage} nyelvű összefoglalót írsz,
ami Telegram-üzenetként megy ki.

Szabályok:
- Forrásonként, azon belül szerzőnként csoportosíts. A csoport fejléce egy emoji és a szerző neve.
- Minden elemnél: egy sor cím, utána 2-6 mondatban a lényeg — a fő állítások, érvek, számok,
  dátumok, árszintek. Ha egy képen grafikon van, olvasd ki belőle a lényeges szinteket.
- Az elem végén a link, külön sorban.
- Csak azt írd le, ami a forrásban szerepel. Ha egy videónál csak a leírás volt elérhető,
  ezt jelezd, és ne találd ki a tartalmát.
- Sima szöveg, Markdown nélkül (a Telegram itt nem jeleníti meg): se **, se #, se táblázat.
- Ne írj bevezetőt vagy zárást; a végén egy rövid "Összegzés" bekezdés jöhet, ha több elem van.`;

const blocks = items.map((it, n) => {
  const note = it.source === 'youtube' && !it.hasTranscript
    ? '\n(Felirat nem érhető el, csak a videó leírása.)' : '';
  const body = (it.text || '').slice(0, cfg.maxCharsPerItem);
  return `### [${n + 1}] ${LABEL[it.source]} — ${it.author}\nCím: ${it.title}\n` +
         `Dátum: ${it.published}\nLink: ${it.url}${note}\n\n${body}`;
});

const content = [{
  type: 'text',
  text: `${items.length} új tartalom érkezett:\n\n${blocks.join('\n\n---\n\n')}`,
}];
let imageCount = 0;
items.forEach((it, n) => {
  for (const url of (it.images || []).slice(0, 2)) {
    if (imageCount >= cfg.maxImages) return;
    content.push({ type: 'text', text: `A [${n + 1}] elemhez tartozó kép:` });
    content.push({ type: 'image', source: { type: 'url', url } });
    imageCount++;
  }
});

return [{
  json: {
    itemCount: items.length,
    body: {
      model: cfg.model,
      max_tokens: 4000,
      system,
      messages: [{ role: 'user', content }],
    },
  },
}];

// A Telegram egy üzenetben legfeljebb 4096 karaktert enged: bekezdéshatáron daraboljuk.
const res = $input.first().json;
const text = (res.content || [])
  .filter(c => c.type === 'text')
  .map(c => c.text)
  .join('\n')
  .trim();
if (!text) throw new Error('A Claude-válasz üres: ' + JSON.stringify(res).slice(0, 500));

const stamp = new Date().toLocaleString('hu-HU', { timeZone: 'Europe/Budapest' });
const LIMIT = 3900;
const chunks = [];
let current = `📰 Content Digest — ${stamp}\n\n`;
for (let para of text.split(/\n{2,}/)) {
  if (current.length + para.length + 2 > LIMIT && current.trim()) {
    chunks.push(current.trim());
    current = '';
  }
  while (para.length > LIMIT) {
    chunks.push(para.slice(0, LIMIT));
    para = para.slice(LIMIT);
  }
  current += para + '\n\n';
}
if (current.trim()) chunks.push(current.trim());

return chunks.map((chunk, i) => ({
  json: { chunk: chunks.length > 1 ? `${chunk}\n\n(${i + 1}/${chunks.length})` : chunk },
}));
